module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

reg [1:0] next_light;
reg [3:0] counter;

always @(posedge clk) begin
    if (reset) begin
        light <= 2'b00;
        walk <= 1'b1;
        counter <= 4'd0;
    end else begin
        if (light == 2'b00) begin // RED
            if (counter == 3'd2) begin
                next_light <= 2'b01; // GREEN
                counter <= 4'd0;
            end else begin
                counter <= counter + 1;
            end
        end else if (light == 2'b01) begin // GREEN
            if (counter == 3'd3) begin
                next_light <= 2'b10; // YELLOW
                counter <= 4'd0;
            end else begin
                counter <= counter + 1;
            end
        end else if (light == 2'b10) begin // YELLOW
            if (counter == 3'd1) begin
                next_light <= 2'b00; // RED
                counter <= 4'd0;
            end else begin
                counter <= counter + 1;
            end
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        light <= 2'b00;
        walk <= 1'b1;
    end else begin
        if (light == 2'b01 && ped) begin // GREEN and ped pressed
            next_light <= 2'b10;
            counter <= 4'd0;
        end else begin
            light <= next_light;
            walk <= (light == 2'b00) ? 1'b1 : 1'b0;
        end
    end
end

endmodule

module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

always @(posedge clk) begin
    if (reset) begin
        light <= 2'b00;
        walk <= 1'b1;
    end else begin
        case (light)
            2'b00: begin
                light <= 2'b01;
                walk <= 1'b0;
            end
            2'b01: begin
                if (ped) begin
                    light <= 2'b10;
                    walk <= 1'b0;
                end else begin
                    light <= 2'b10;
                    walk <= 1'b0;
                end
            end
            2'b10: begin
                light <= 2'b00;
                walk <= 1'b1;
            end
            default: begin
                light <= 2'b00;
                walk <= 1'b1;
            end
        endcase
    end
end

endmodule

