module mac (
    input clk,
    input reset,
    input clear,
    input en,
    input signed [7:0] a,
    input signed [8:0] b,  // Using 9 bits to handle signed multiplication
    output reg signed [19:0] acc
);

always @(posedge clk) begin
    if (reset) begin
        acc <= 20'd0;
    end else begin
        if (clear) begin
            acc <= 20'd0;
        end else if (en) begin
            // Compute a * b as a signed 16-bit product
            reg signed [15:0] product;
            product = a * b;
            // Add product to acc, wrapping around on overflow
            acc <= acc + product;
        end
    end
end

endmodule

